// Matriculas curtas vao inteiras; nas longas, janelas em volta das palavras-chave
// de descricao de perimetro, mescladas, com o cabecalho (endereco) na frente.
const texto = $('Preparar Input').first().json.texto_ocr || '';
const LIMITE = 12000;
if (texto.length <= LIMITE) {
  return [{ json: { recorte: texto, recorte_chars: texto.length, texto_completo: true } }];
}
const RE = /(medindo|metros?\s+de\s+frente|de\s+frente\s+para|da\s+frente\s+aos\s+fundos|confront|\barea\s+de|\bárea\s+de|superf[ií]cie\s+de|encerrando\s+a\s+[aá]rea|per[ií]metro|azimute|deflete|deflex[aã]o|[aâ]ngulo\s+interno|rumo\s+[NS]|coordenadas|UTM|assim\s+descrit|descri[cç][aã]o\s+do\s+im[oó]vel|bra[cç]as?|lateral\s+(direita|esquerda)|\bfundos\b|chanfr|testada)/gi;
const janelas = [];
let m;
while ((m = RE.exec(texto)) !== null) {
  janelas.push([Math.max(0, m.index - 1200), Math.min(texto.length, m.index + 1800)]);
  if (janelas.length > 60) break;
}
janelas.sort((a, b) => a[0] - b[0]);
const blocos = [];
for (const j of janelas) {
  const ult = blocos[blocos.length - 1];
  if (ult && j[0] <= ult[1]) ult[1] = Math.max(ult[1], j[1]);
  else blocos.push([...j]);
}
let recorte = texto.slice(0, 1500);
for (const [a, b] of blocos) {
  if (recorte.length > 20000) break;
  recorte += '\n[...]\n' + texto.slice(a, b);
}
recorte = recorte.slice(0, 22000);
if (blocos.length === 0) recorte = texto.slice(0, 20000);
return [{ json: { recorte, recorte_chars: recorte.length, texto_completo: false } }];

