const bruto = resp?.choices?.[0]?.message?.content;
if (!bruto) throw new Error('Extracao sem resposta do modelo');
let texto = String(bruto).trim();
texto = texto.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let dados = null;
try { dados = JSON.parse(texto); } catch (e) {
  const ini = texto.indexOf('{');
  const fim = texto.lastIndexOf('}');
  if (ini >= 0 && fim > ini) {
    try { dados = JSON.parse(texto.slice(ini, fim + 1)); } catch (e2) {}
  }
}
if (!dados || typeof dados !== 'object' || Array.isArray(dados)) {
  throw new Error('Extracao nao retornou JSON valido: ' + texto.slice(0, 200));
}
if (!dados.formato) { dados.formato = 'nao_identificado'; dados.croqui_viavel = false; }
if (!Array.isArray(dados.segmentos)) dados.segmentos = [];
return [{ json: { extracao: dados } }];

const extracao = $input.first().json.extracao || {};
const prep = $('Preparar Input').first().json;
const rec = $('Recortar Perimetro').first().json;
const result = {
  ...extracao,
  total_paginas: prep.total_paginas ?? null,
  recorte_chars: rec.recorte_chars ?? null,
  texto_completo: rec.texto_completo ?? null,
};
// Uso real do modelo para telemetria de margem (painel Admin > Custos)
const _u = ($('Extracao Croqui').first().json || {}).usage || {};
const _in = Number(_u.prompt_tokens) || 0;
const _out = Number(_u.completion_tokens) || 0;
// Precos mistral-medium-latest: US$0,4/1M input, US$2/1M output
const _cost = Number(((_in * 0.4 + _out * 2) / 1e6).toFixed(6));
const usage = { models: [{ workflow: 'lidimus-croqui', model: 'mistral-medium-latest', promptTokens: _in, completionTokens: _out, totalTokens: _in + _out, costUsd: _cost }] };
return [{ json: { jobId: prep.jobId, stage: 'croqui', result, usage } }];

