// Saída única de falha do caminho principal. O "Responder Webhook" já devolveu
// 200 lá no começo, então o worker do Lidimus considera o disparo bem-sucedido:
// falha que não chega aqui não chega a lugar nenhum, e o job fica em
// `processing` até o watchdog varrer.
const item = $input.first().json || {};

// $prevNode é quem entregou o item nesta execução, e só a saída de erro chega
// aqui — logo, é sempre o nó que falhou.
let noQueFalhou = '';
try { noQueFalhou = $prevNode.name || ''; } catch (e) {}

const err = (item.error && typeof item.error === 'object') ? item.error : {};
const bruto = err.message || item.error || item.message || 'Falha na extração do croqui';

// O nó HTTP embrulha a resposta da API em "... Status 4xx\nBody: {json}".
// Quem lê o erro na tela quer a frase de dentro, não o envelope.
function desembrulhar(txt) {
  const m = String(txt).match(/Body:\s*(\{[\s\S]*\})\s*$/);
  if (!m) return String(txt);
  try {
    const b = JSON.parse(m[1]);
    const dentro = b.message || (b.error && (b.error.message || b.error)) || null;
    return dentro ? String(dentro) : String(txt);
  } catch (e) { return String(txt); }
}

const partes = [desembrulhar(typeof bruto === 'object' ? JSON.stringify(bruto) : bruto)];
// `description` costuma trazer a causa real quando `message` é genérico
// ("Bad request - please check your parameters").
if (err.description && !partes.includes(String(err.description))) partes.push(String(err.description));

const detalhe = partes.join(' — ').replace(/\s+/g, ' ').trim();
const onde = noQueFalhou ? ' (' + noQueFalhou + ')' : '';
let execucao = '';
try { execucao = ' [execução ' + $execution.id + ']'; } catch (e) {}

return [{ json: { errorMessage: ('Falha na extração do croqui' + onde + ': ' + detalhe + execucao).slice(0, 500) } }];

